<?php
declare(strict_types=1);require_once __DIR__.'/_auth.php';require_once __DIR__.'/../vendor/autoload.php';
use EnglAI\Analytics\AnalyticsService;use EnglAI\Analytics\AuditService;use EnglAI\Mvp\ClassroomService;
require_admin();$cid=(int)($_GET['classroom_id']??0);$actor=(string)($_SESSION['admin_username']??'admin');$classroom=(new ClassroomService(db()))->requireOwned($cid,$actor);$data=(new AnalyticsService(db()))->classroom($cid);$q=db()->prepare('SELECT original_name FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1');$q->execute([$cid]);$rpp=(string)($q->fetchColumn()?:'—');(new AuditService(db()))->record($cid,$actor,'report.exported','print_report',null,[],['type'=>'classroom_print']);
