<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Classroom Summary · EnglAI</title><link rel="stylesheet" href="/assets/css/analytics.css"></head><body><main class="print-report"><button class="no-print" onclick="window.print()">Print</button><h1>EnglAI Classroom Summary</h1><p><b><?=htmlspecialchars($classroom['name'])?></b> · <?=htmlspecialchars($classroom['code'])?></p><p>RPP: <?=htmlspecialchars($rpp)?> · Level: <?=ucfirst($data['classroom_level'])?> · Generated: <?=date('Y-m-d H:i')?></p><hr><h2>Overview</h2><table><tr><th>Students</th><th>Completion</th><th>Self Learning Avg</th><th>Live Quiz Avg</th></tr><tr><td><?=$data['students']?></td><td><?=$data['completion_rate']?>%</td><td><?=$data['self_learning_average']?>%</td><td><?=$data['live_quiz_average']?>%</td></tr></table><h2>Skill Performance</h2><table><thead><tr><th>Skill</th><th>Attempts</th><th>Average</th><th>Completion</th></tr></thead><tbody><?php foreach($data['skills'] as $s=>$v):?><tr><td><?=ucfirst($s)?></td><td><?=$v['attempts']?></td><td><?=$v['average']?>%</td><td><?=$v['completion']?>%</td></tr><?php endforeach;?></tbody></table><h2>Competency Performance</h2><table><thead><tr><th>Competency</th><th>Average</th><th>Status</th></tr></thead><tbody><?php foreach($data['competencies'] as $r):?><tr><td><?=htmlspecialchars($r['competency'])?></td><td><?=number_format((float)$r['average'],1)?>%</td><td><?=$r['status']?></td></tr><?php endforeach;?></tbody></table></main></body></html>
